public final class PaddockPatchRequestDeserializer extends StdDeserializer<PaddockController.PatchRequest>{public PaddockPatchRequestDeserializer(){super(PaddockController.PatchRequest.class);}public PaddockController.PatchRequest deserialize(JsonParser p,DeserializationContext c)throws IOException{p.enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION.mappedFeature());JsonNode x=p.getCodec().readTree(p);HerdMovementRequestDeserializer.fields(p,x,Set.of("expectedVersion","name","code","status"));Long v=x.has("expectedVersion")&&!x.get("expectedVersion").isNull()?HerdMovementRequestDeserializer.number(p,x,"expectedVersion"):null;return new PaddockController.PatchRequest(v,text(p,x,"name"),text(p,x,"code"),status(p,x));}private static HerdAnimalPatch<String> text(JsonParser p,JsonNode x,String f)throws JsonMappingException{if(!x.has(f))return HerdAnimalPatch.absent();JsonNode n=x.get(f);if(n.isNull())return HerdAnimalPatch.present(null);if(!n.isTextual())throw JsonMappingException.from(p,"Texto inválido");return HerdAnimalPatch.present(n.textValue());}private static HerdAnimalPatch<PaddockStatus> status(JsonParser p,JsonNode x)throws JsonMappingException{if(!x.has("status"))return HerdAnimalPatch.absent();JsonNode n=x.get("status");if(n.isNull())return HerdAnimalPatch.present(null);if(!n.isTextual())throw JsonMappingException.from(p,"Status inválido");try{return HerdAnimalPatch.present(PaddockStatus.valueOf(n.textValue()));}catch(Exception e){throw JsonMappingException.from(p,"Status inválido",e);}}}
